profile=json.loads(Path('00_FINAL_PIPELINE_CORE/registry/path_profiles/'+g['path_id']+'.json').read_text())
sc='scenario.exercise_operations'
texts=[]
for b in g['bundles']:
    texts.extend(t['content'] for t in b['teaching_blocks'])
    texts.append(json.dumps({k:b.get(k) for k in ['visual_anchor','practice_anchor','assessment_anchors']},ensure_ascii=False))
text='\n'.join(texts)
terms=['GitHub Actions','unit','integration','promotion','continue-on-error','EC2','CI','CloudFormation','S3','CloudTrail','Automation','aws:approve','Object Lock','governance','compliance','root','Terraform','Inspector','CodePipeline','Lambda','system status checks','instance checks','container','exit status','smoke check','backup-read','recovery-resource','execution ID','acting role','targets','start/end times','step statuses','inputs','outputs','failure information','request identity','operation evidence','retention mode','retain-until date','BUCKET','KEY','REGION','ARN','TIME','TEST_COMMAND','UNIT_JOB','INTEGRATION_JOB','FILES','MESSAGE','create_before_destroy','prevent_destroy','terraform init -migrate-state','PutJobSuccessResult','PutJobFailureResult','two-AZ','production','account','Region','approved tags','delete markers','saved plan','artifact revision','service logs','protected operation','stop conditions']
vocab=sorted(set(t for t in terms if t in text)|set(re.findall(r'--[a-z][a-z-]+',text)))
assets=[]
def add(i,short,spec,rows):
    # Dataset records are fictional, read-only evidence fixtures, not executed services.
    cols=[]
    for name,typ,role,desc in spec:
        c=dict(name=name,type=typ,semantic_role=role,description=desc)
        if role in ['identifier','categorical'] and any(isinstance(r[len(cols)],str) and r[len(cols)].isdigit() for r in rows): c['numeric_looking_label']=True
        cols.append(c)
    b=g['bundles'][i]
    assets.append(dict(asset_id='ds.'+short,asset_kind='dataset',scenario_id=sc,title=b['context']['concept_name']+' — read-only evidence',description='Authored fictional exercise records for '+b['context']['concept_id']+'. Observations are supplied for inspection only; no runtime, cloud resource or credentials are provisioned.',columns=cols,rows=rows,provenance='authored'))
def ident(n,d):return (n,'string','identifier',d)
def cat(n,d):return (n,'string','categorical',d)
def txt(n,d):return (n,'string','text',d)
def num(n,d):return (n,'integer','numerical',d)
def dt(n,d):return (n,'datetime','datetime',d)
def date(n,d):return (n,'date','datetime',d)
def flag(n,d):return (n,'boolean','categorical',d)
start=datetime(2026,1,15,10,0,tzinfo=timezone.utc)
def time(minutes):return (start+timedelta(minutes=minutes)).isoformat()
# Command status is a supplied observation; dependent status is derived from the taught rule.
exits={'UNIT_JOB':1,'INTEGRATION_JOB':0}
add(0,'test_gates',[ident('job','Workflow job label'),txt('needs','Required job labels'),num('exit_status','Supplied command exit-status observation; missing for unrun job'),cat('job_status','Observed job state'),flag('continue_on_error','Whether failure is tolerated')],[[j,'',v,'success' if v==0 else 'failure',False] for j,v in exits.items()]+[['promotion',', '.join(exits),None,'skipped' if any(exits.values()) else 'success',False]])
add(1,'change_record',[ident('change_id','One focused change record'),cat('evidence_kind','Review or execution evidence category'),txt('evidence','Supplied record detail')],[['change-exercise','intent','Focused approved EC2 configuration change'],['change-exercise','diff','Only the supplied EC2 resource arguments changed'],['change-exercise','commit_reference','exercise-focused-commit on the supplied review branch'],['change-exercise','saved_plan','Approved saved plan for the affected exercise EC2 resource'],['change-exercise','approval','Supplied reviewer approval before CI apply'],['change-exercise','execution','CI applied the approved saved plan'],['change-exercise','verification','Resulting exercise instance verified']])
add(2,'az_availability',[ident('case_id','Controlled failure case'),cat('failed_scope','Approved AZ component boundary'),txt('abort_criteria','Supplied experiment stop criterion'),flag('independent_capacity_remains','Supplied remaining-capacity observation'),cat('remaining_request_path','Supplied client-path observation'),cat('client_required_behavior','Supplied client-request check observation')],[['az-path-fails','supplied AZ components','Stop on reaching supplied client failure limit',True,'unavailable','fail'],['az-path-passes','supplied AZ components','Stop on reaching supplied client failure limit',True,'available','pass']])
add(3,'teardown',[ident('resource','Exercise-only resource or dependent collection'),txt('scope_evidence','Approved membership or tag evidence'),txt('remove_before','Prerequisite that requires dependent removal first'),cat('deletion_result','Supplied deletion observation'),txt('follow_up','Required approved follow-up')],[['objects','approved exercise stack','S3 bucket','removed',''],['object versions','approved exercise stack','S3 bucket','removed',''],['delete markers','approved exercise stack','S3 bucket','removed',''],['S3 bucket','approved exercise stack','','removed',''],['retained exercise resource','approved exercise stack','','retained','Inspect retention and obtain approved follow-up'],['failed exercise resource','approved exercise tags','','failed','Inspect failure and obtain approved follow-up']])
expiry=time(90)
add(4,'recovery_readiness',[ident('session','Session label, not a credential'),ident('acting_role','Fictional approved role label'),dt('checked_at','Session inspection time'),dt('expires_at','Supplied session expiry'),cat('backup_read','Supplied backup-read authorization test'),cat('recovery_resource','Supplied recovery-resource authorization test')],[['recovery-denied','exercise-recovery-role',time(0),expiry,'denied','allowed'],['recovery-ready','exercise-recovery-role',time(10),expiry,'allowed','allowed']])
add(5,'rehearsal_targets',[cat('setting','Rehearsal destination setting'),ident('account','Fictional account label, not quantity'),cat('target_environment','Target boundary'),txt('destination','Fictional destination label'),txt('approved_scope','Supplied rehearsal boundary'),txt('stop_condition','Supplied stop boundary')],[['restoration','exercise-isolated-account','isolated recovery','exercise-recovery-network','isolated recovery only','Stop if a destination points to production'],['client test traffic','exercise-isolated-account','isolated recovery','exercise-recovery-endpoint','isolated recovery only','Stop if a destination points to production']])
add(6,'approval_states',[ident('execution_id','Fictional execution label'),cat('approval_step','Supplied approval action'),cat('execution_state','Supplied observed execution state'),flag('protected_operation_executed','Supplied protected-operation observation')],[[f'approval-{state}','aws:approve',state,False] for state in ['pending','rejected','stopped']])
audit=[]
for j,(step,status,operation,output,failure) in enumerate([('read_backup','Success','GetObject','Backup-read test allowed',''),('create_recovery','Failed','CreateStack','','Supplied recovery-resource test denied')]):
    audit.append(['response-exercise','exercise-recovery-role','exercise-backup' if j==0 else 'exercise-recovery-stack',time(0),time(5),step,time(j),time(j+1),status,'Supplied exercise target',output,failure,'request-'+step,'exercise-recovery-role',operation])
add(7,'response_audit',[ident('execution_id','Automation execution identity shared by both steps'),ident('acting_role','Acting role label; no credentials'),ident('target','Underlying action target'),dt('start_time','Execution start'),dt('end_time','Execution end'),ident('step','Automation step label'),dt('step_start_time','Step start'),dt('step_end_time','Step end'),cat('step_status','Supplied Automation step status'),txt('inputs','Step input record'),txt('outputs','Step output record; empty for failed step'),txt('failure_information','Failure detail; empty for successful step'),ident('cloudtrail_request_id','Corresponding CloudTrail request identifier'),ident('cloudtrail_request_identity','Supplied request identity that attributes the action'),cat('cloudtrail_operation','Corresponding underlying AWS operation')],audit)
add(8,'integrity_scope',[ident('trail','Supplied trail label; not a literal ARN'),ident('account','Fictional organization account label'),cat('region','Supplied Region placeholder'),dt('start_time','Validation interval start'),dt('end_time','Validation interval end'),ident('log_set','Supplied log/digest set label'),cat('validation_result','Supplied integrity observation'),txt('failure_information','Seeded validation failure evidence')],[['exercise-organization-trail','exercise-isolated-account','REGION',time(0),time(60),'logs-intact','pass',''],['exercise-organization-trail','exercise-isolated-account','REGION',time(60),time(120),'logs-seeded-failure','fail','Delivered log modification detected in the supplied digest interval']])
required_end=(start+timedelta(days=30)).date()
retention=[]
for j,mode in enumerate(['governance','compliance']):
    retention.append(['exercise-audit-bucket','response-audit','version-'+mode,mode,start.date().isoformat(),required_end.isoformat(),required_end.isoformat(),mode=='governance',mode=='governance'])
add(9,'audit_retention',[ident('bucket','Prepared fictional Object Lock audit bucket label'),ident('object_key','Audit-object key label'),ident('version_id','Individual object-version identity'),cat('retention_mode','Version-specific Object Lock mode'),date('required_start_date','Supplied required retention interval start'),date('required_end_date','Supplied required retention interval end'),date('retain_until_date','Inspected version-specific retain-until date'),flag('bypass_authorization','Whether governance bypass authority is supplied'),flag('bypass_requested','Whether governance bypass is explicitly requested')],retention)
add(10,'backend_sequence',[num('sequence','Sequence ordinal, not a label'),cat('step','Backend workflow stage'),txt('evidence','Supplied workflow observation'),ident('bucket','Supplied BUCKET placeholder'),ident('key','Supplied KEY placeholder'),cat('region','Supplied REGION placeholder')],[[j+1,step,evidence,'BUCKET','KEY','REGION'] for j,(step,evidence) in enumerate([('local-state bootstrap','Protected bucket provisioned with supplied settings'),('backend selection','Backend selects the already-existing bucket and key'),('approved migration','Supplied migration approved before terraform init -migrate-state'),('destination inspection','Exercise state found at the intended bucket/key')])])
add(11,'replacement_controls',[ident('plan','Controlled plan label'),cat('lifecycle_setting','Configured lifecycle argument'),txt('triggering_diff','Supplied controlled replacement-triggering change'),cat('plan_outcome','Supplied plan order or prevention observation'),txt('scope_impact_approval','Separate approval evidence')],[['replacement-default','default','Supplied replacement-triggering EC2 argument edit','destroy before create','Supplied approval required before permitted apply'],['replacement-reversed','create_before_destroy','Supplied replacement-triggering EC2 argument edit','create before destroy where supported','Supplied approval required before permitted apply'],['replacement-prevented','prevent_destroy','Supplied replacement-triggering EC2 argument edit','destruction plan rejected while rule remains configured','Rejected plan is not applied']])
add(12,'restoration_checks',[ident('case_id','Isolated restoration case'),ident('account','Fictional isolated account label'),cat('region','Supplied Region placeholder'),ident('execution_authority','Approved recovery role label'),ident('template','Supplied restoration template label'),txt('parameters','Supplied template parameter record'),cat('stack_events','Supplied completed creation observation'),ident('resource_id','Fictional created resource label'),txt('outputs','Supplied stack output record'),cat('instance_check','Supplied instance recovery-ready check'),cat('service_check','Supplied service recovery-ready check')],[['restore-service-fails','exercise-isolated-account','REGION','exercise-recovery-role','supplied-ec2-template','Supplied isolated network and instance parameters','creation complete','exercise-recovery-instance','Instance: exercise-recovery-instance','pass','fail'],['restore-service-passes','exercise-isolated-account','REGION','exercise-recovery-role','supplied-ec2-template','Supplied isolated network and instance parameters','creation complete','exercise-recovery-instance','Instance: exercise-recovery-instance','pass','pass']])
add(13,'security_findings',[ident('finding_id','Fictional finding record label'),ident('affected_resource','Fictional image/dependency resource label'),txt('vulnerability_evidence','Supplied scan evidence, not an invented real CVE'),cat('severity','Supplied finding severity category'),cat('threshold','Supplied exercise policy threshold'),txt('exception_basis','Documented exception if applicable'),cat('policy_result','Computed from supplied exercise threshold and exception'),cat('promotion','Dependent progression derived from policy')],[[f'finding-{j}','exercise-image','Supplied scan report identifies an affected image dependency','HIGH','HIGH',exc,'pass' if exc else 'fail','permitted by this gate' if exc else 'blocked'] for j,exc in enumerate(['','Supplied documented exception covers this finding'])])
add(14,'pipeline_actions',[ident('execution_id','Selected execution or intended-input retest'),ident('revision','Intended input artifact revision label'),cat('action','Pipeline action'),cat('status','Supplied action observation'),txt('error_details','Supplied failed-action detail'),txt('linked_service_logs','Relevant supplied service evidence'),txt('approved_correction','Supplied evidence-supported correction')],[['pipeline-original','exercise-revision','source','success','','',''],['pipeline-original','exercise-revision','build','failed','Supplied build command failed','Build service log records the supplied command failure','Apply supplied build correction'],['pipeline-original','exercise-revision','deployment','did not run','','',''],['pipeline-retest','exercise-revision','build','success','','Retest build service log confirms intended-input success','Supplied build correction applied']])
add(15,'health_inspection',[ident('workload','Affected fictional workload label'),dt('interval_start','Correlated telemetry interval start'),dt('interval_end','Correlated telemetry interval end'),cat('component','Inspected component'),txt('telemetry','Supplied metric and log symptom'),cat('container_state','Supplied container state'),num('exit_status','Supplied exit-status observation; not executed here'),txt('recent_logs','Supplied component inspection evidence'),cat('health_check','Supplied health-check observation'),txt('correction','Supplied approved correction or remaining failure')],[['exercise-container',time(0),time(5),'application container','Client request health checks fail','exited',1,'Supplied log identifies a component configuration error','fail','Supplied approved component configuration correction'],['exercise-container',time(5),time(10),'application container','Metric improved after component correction','running',None,'Component restarted after supplied correction','fail','Retain required failed health check; metric improvement is insufficient'],['exercise-container',time(10),time(15),'application container','Repeated client request check','running',None,'Component inspection consistent with supplied correction','pass','Supplied correction verified by repeated health check']])
add(16,'smoke_checks',[ident('job_id','Fictional validation job label'),ident('revision','Expected deployed revision label'),ident('endpoint','Fictional deployed endpoint label, not a URL'),cat('deployment_status','Supplied operation completion'),txt('expected_response','Supplied revision behavior requirement'),cat('observed_response','Supplied behavior comparison'),cat('job_result_call','Derived CodePipeline reporting path'),cat('dependent_progression','Derived gate outcome')],[[f'smoke-{j}','exercise-revision','exercise-service-endpoint','completed','Supplied expected response for exercise-revision',result,'PutJobSuccessResult' if result=='matches' else 'PutJobFailureResult','permitted by this gate' if result=='matches' else 'blocked'] for j,result in enumerate(['does not match','matches'])])
registry=dict(schema_version='1.0',kind='scenario_asset_registry',path_id=g['path_id'],batch_id=B.name,scenarios=[dict(scenario_id=sc,name='Exercise operations review desk',summary='A fictional operations team reviews supplied delivery, response, recovery and cleanup evidence for one bounded training workload. All records are authored read-only examples; production stays outside the rehearsal target and no infrastructure is provisioned.',domain='AWS delivery and operational recovery',glossary_example_vocab=vocab)],assets=assets)
# Own mistakes-to-avoid checklist: width, role/type, identifiers, duplicates, scope,
# table-anchor completeness, and no unsupported runtime or rendered-plot requirement.
assert len(assets)==len(g['bundles'])
assert len({a['asset_id'] for a in assets})==len(assets)
for a in assets:
    assert a['rows'] and len({c['name'] for c in a['columns']})==len(a['columns'])
    for r in a['rows']:
        assert len(r)==len(a['columns'])
        for c,v in zip(a['columns'],r):
            if v is None: continue
            if c['type']=='integer': assert isinstance(v,int) and not isinstance(v,bool)
            elif c['type']=='boolean': assert isinstance(v,bool)
            else: assert isinstance(v,str)
            if isinstance(v,str) and v.isdigit() and c['semantic_role'] in ('identifier','categorical'): assert c['numeric_looking_label']
    for c in a['columns']:
        assert (c['semantic_role']=='numerical')==(c['type'] in ['integer','number'])
    assert not a.get('variants') # no messy mutations needed for inspect-and-judge records
for i,b in enumerate(g['bundles']):
    assert assets[i]['description'].find(b['context']['concept_id'])>=0
    assert b['practice_anchor']['type']=='field_selection' or b['context']['concept_id'] in profile['practice_type_by_concept']
    assert b['visual_anchor']['type'] not in ('chart','plot')
(B/'scenario_asset_registry.json').write_text(json.dumps(registry,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'scenarios':len(registry['scenarios']),'concepts':len(g['bundles']),'assets':len(assets),'rows':sum(len(a['rows']) for a in assets),'variants':0,'images':0,'asset_ids':[a['asset_id'] for a in assets]},indent=2))
